/**
 * @author Brian Wing Shun Chan
 */
@Component(
	property = "model.class.name=it.servizidigitali.gestionebandi.model.DatoBando",
	service = AopService.class
)
public class DatoBandoLocalServiceImpl extends DatoBandoLocalServiceBaseImpl {
	public static final Log _log = LogFactoryUtil.getLog(DatoBandoLocalServiceImpl.class);

	@Override
	public DatoBando findByCodice(String codiceDatoBando) {
		try{
			return datoBandoPersistence.findByCodice(codiceDatoBando);
		}
		catch(NoSuchDatoBandoException e){
			_log.error(e.getMessage(), e);
			throw new RuntimeException(e.getMessage(), e);
		}
	}
}

